-- AI Podcast (aipodcast.jasonlin.tech) read API: static files generated by
-- pipeline/gen_kindle_api.py in the same shape as Qiaomu AI RSS.
-- All news data stays outside the book library and ReadHistory.
local JSON = require("json")
local DataStorage = require("datastorage")
local M = { ORIGIN = "https://aipodcast.jasonlin.tech", API = "/kindle/api", LIMIT = 60, MAX_ITEMS = 200,
    MAX_BODY = 2500000 }   -- bilingual full transcripts run far past the 400 KB of a news article
local state

local function root()
    local dir = DataStorage:getSettingsDir() .. "/simpleui/news"
    require("util").makePath(dir .. "/articles")
    return dir
end

local function read(path)
    local f = io.open(path, "rb")
    if not f then return end
    local s = f:read("*a"); f:close()
    if #s > 4 * 1024 * 1024 then return end
    local ok, value = pcall(JSON.decode, s)
    if ok and type(value) == "table" then return value end
end

local function write(path, value)
    local f, err = io.open(path .. ".tmp", "wb")
    assert(f, err)
    local ok, why = f:write(JSON.encode(value))
    local closed, close_err = f:close()
    assert(ok and closed, why or close_err)
    assert(os.rename(path .. ".tmp", path))
end

function M.validId(id)
    return type(id) == "string" and #id <= 128 and id:match("^[%w_-]+$") ~= nil
end

function M.state()
    if not state then
        state = read(root() .. "/index.json") or {}
        for _, key in ipairs{ "entries", "sources", "flags" } do
            if type(state[key]) ~= "table" then state[key] = {} end
        end
        -- Older builds saved sources without categories, which channels need.
        local categorized = false
        for _, source in ipairs(state.sources) do
            if source.category then categorized = true; break end
        end
        if not categorized then
            local preset = read(require("infra/sui_paths").getPluginDir() .. "data/qiaomu_sources.json")
            if preset and type(preset.sources) == "table" then state.sources = preset.sources end
        end
    end
    return state
end

function M.save() write(root() .. "/index.json", M.state()) end

local function text(value, limit)
    if type(value) ~= "string" then return "" end
    -- Do not split UTF-8 in the middle of a character.
    if #value > limit then return "" end
    return value
end

function M.title(entry)
    return type(entry.titleZh) == "string" and entry.titleZh ~= "" and entry.titleZh or entry.title
end

function M.merge(entries, sources)
    assert(type(entries) == "table", "Invalid article list")
    local s, merged, seen = M.state(), {}, {}
    local names = {}
    if type(sources) == "table" then
        local clean = {}
        for _, source in ipairs(sources) do
            if type(source) == "table" and M.validId(source.id) and type(source.name) == "string" and source.enabled ~= false then
                clean[#clean + 1] = { id = source.id, name = text(source.name, 500),
                    category = text(source.category, 64), siteUrl = text(source.siteUrl, 2000) }
                names[source.id] = source.name
            end
        end
        s.sources = clean
    end
    for _, source in ipairs(s.sources) do names[source.id] = source.name end
    for _, raw in ipairs(entries) do
        if type(raw) == "table" and M.validId(raw.id) and type(raw.title) == "string" and not seen[raw.id] then
            seen[raw.id] = true
            merged[#merged + 1] = {
                id = raw.id, title = text(raw.title, 4000), titleZh = text(raw.titleZh, 4000),
                sourceId = text(raw.sourceId, 128), sourceName = names[raw.sourceId] or text(raw.sourceName, 500),
                published = text(raw.published, 100), publishedTs = tonumber(raw.publishedTs) or 0,
                link = text(raw.link, 4000),
                image = text(raw.image, 4096),
            }
        end
        if #merged >= M.MAX_ITEMS then break end
    end
    -- Keep older saved articles and their reading positions across refreshes.
    for _, entry in ipairs(s.entries) do
        if M.validId(entry.id) and not seen[entry.id] then
            if #merged < M.MAX_ITEMS or (s.flags[entry.id] or {}).starred then
                merged[#merged + 1] = entry
                seen[entry.id] = true
            end
        end
    end
    for id in pairs(s.flags) do
        if not seen[id] then
            if M.validId(id) then os.remove(root() .. "/articles/" .. id .. ".json") end
            s.flags[id] = nil
        end
    end
    table.sort(merged, function(a, b)
        if a.publishedTs ~= b.publishedTs then return a.publishedTs > b.publishedTs end
        return a.id < b.id
    end)
    s.entries, s.updated_at = merged, os.time()
    M.save()
end

function M.flag(id)
    assert(M.validId(id), "Invalid article ID")
    local s = M.state()
    s.flags[id] = s.flags[id] or {}
    return s.flags[id]
end

function M.cached(id)
    assert(M.validId(id), "Invalid article ID")
    local article = read(root() .. "/articles/" .. id .. ".json")
    if article and type(article.body) == "string" and #article.body > 0
            and #article.body <= M.MAX_BODY and (article.format == "html" or article.format == "md") then
        require("features/sui_news_cache").touch(root() .. "/articles/" .. id .. ".json")
        return article
    end
end

function M.cache(id, article)
    assert(M.validId(id), "Invalid article ID")
    assert(type(article.body) == "string" and #article.body > 0 and #article.body <= M.MAX_BODY,
        "Article is empty or too large for this device")
    assert(article.format == "md" or article.format == "html", "Invalid article format")
    if not require("features/sui_news_cache").makeRoom(#JSON.encode(article), M.state()) then
        return nil, "News cache is full"
    end
    write(root() .. "/articles/" .. id .. ".json", article)
    M.flag(id).offline = true
    M.save()
end

-- Requests run in KOReader's cancellable subprocess, never in a new service.
local function shellQuote(value)
    return "'" .. value:gsub("'", "'\\''") .. "'"
end

local function curlRequest(path, max_time)
    -- Kindle's built-in curl uses its system TLS/CA stack. LuaSec can stall
    -- on these same CDN handshakes. No external program is installed.
    local last_error
    for i = 1, 2 do
        local command = "/usr/bin/curl --silent --fail --compressed --ipv4 --connect-timeout 8 --max-time " .. tostring(max_time or 25)
            .. " --max-filesize 4194304 --proto '=https'"
            .. " --header 'Accept: application/json'"
            .. " --user-agent 'KOReader-SimpleUI-AIPodcast/1.0'"
            .. " --write-out '\\n%{http_code}'"
        command = command .. " " .. shellQuote(M.ORIGIN .. path)
            .. " 2>/dev/null; qiaomu_news_exit=$?; printf '\\n%s' \"$qiaomu_news_exit\""
        local pipe = io.popen(command, "r")
        if not pipe then return nil, "Could not start network request" end
        local chunks, size, oversized = {}, 0, false
        while true do
            local chunk = pipe:read(65536)
            if not chunk then break end
            size = size + #chunk
            if size > 4 * 1024 * 1024 then oversized = true; break end
            chunks[#chunks + 1] = chunk
        end
        local closed, _, exit_code = pipe:close()
        if oversized then return nil, "Response too large" end
        local body, status, curl_status = table.concat(chunks):match("^(.*)\n(%d%d%d)\n(%d+)$")
        local failed = tonumber(curl_status) ~= 0 or closed == false or (exit_code ~= nil and exit_code ~= 0)
        if tonumber(status) == 200 and not failed then
            local ok, data = pcall(JSON.decode, body)
            if ok and type(data) == "table" then return data end
            return nil, "Invalid response"
        end
        last_error = tonumber(status) and tonumber(status) >= 300 and ("HTTP " .. status)
            or ("Network transfer incomplete (" .. tostring(curl_status) .. ")")
        if tonumber(status) and tonumber(status) >= 300 then break end
    end
    return nil, last_error
end

function M.request(path, max_time)
    assert(path:sub(1, #M.API) == M.API or path:sub(1, 10) == "/mcp-data/", "Invalid API path")
    local Device = require("device")
    local curl = Device.isKindle and Device:isKindle() and io.open("/usr/bin/curl", "rb")
    if curl then curl:close(); return curlRequest(path, max_time) end
    local http, socketutil = require("socket.http"), require("socketutil")
    local chunks, size, started = {}, 0, os.time()
    socketutil:set_timeout(5, 15)
    local options = {
        url = M.ORIGIN .. path, method = "GET", redirect = false,
        headers = { ["User-Agent"] = "KOReader-SimpleUI-AIPodcast/1.0", Accept = "application/json" },
        sink = function(chunk)
            if chunk then
                size = size + #chunk
                if size > 4 * 1024 * 1024 then return nil, "Response too large" end
                if os.time() - started > 15 then return nil, "Request timed out" end
                chunks[#chunks + 1] = chunk
            end
            return 1
        end,
    }
    local ok, result, code = pcall(http.request, options)
    socketutil:reset_timeout()
    if not ok or tonumber(code) ~= 200 then
        return nil, "HTTP " .. tostring(code or result or "network error")
    end
    local decoded, data = pcall(JSON.decode, table.concat(chunks))
    if not decoded or type(data) ~= "table" then return nil, "Invalid response" end
    return data
end

function M.fetchIndex(source)
    if source ~= nil then assert(M.validId(source), "Invalid source ID") end
    local path = source and (M.API .. "/sources/" .. source .. "/entries") or (M.API .. "/entries")
    local entries, err = M.request(path .. "?limit=" .. M.LIMIT)
    if not entries or type(entries.entries) ~= "table" then return nil, err or "Invalid article list" end
    -- Source names ship with the plugin and can be refreshed separately:
    -- a large or unavailable catalog must not hold up the latest articles.
    return { entries = entries.entries }
end

--- Latest entries of a channel group: one combined request, then the
--- missing sources individually (bounded, so a large group stays quick).
function M.fetchGroup(ids, extra_limit)
    local entries, present, last_error = {}, {}, nil
    local wanted = {}
    for _, id in ipairs(ids) do assert(M.validId(id), "Invalid source ID"); wanted[id] = true end
    local all, err = M.request(M.API .. "/entries?limit=" .. M.MAX_ITEMS)
    if all and type(all.entries) == "table" then
        for _, entry in ipairs(all.entries) do
            if type(entry) == "table" and wanted[entry.sourceId] then
                entries[#entries + 1] = entry; present[entry.sourceId] = true
            end
        end
    else
        last_error = err
    end
    local fetched = 0
    for _, id in ipairs(ids) do
        if not present[id] and fetched < (extra_limit or 8) then
            fetched = fetched + 1
            local page, page_err = M.request(M.API .. "/sources/" .. id .. "/entries?limit=8")
            if page and type(page.entries) == "table" then
                for _, entry in ipairs(page.entries) do entries[#entries + 1] = entry end
            else
                last_error = page_err
            end
        end
    end
    if #entries == 0 and last_error then return nil, last_error end
    return { entries = entries }
end

local function esc(value)
    return (tostring(value or ""):gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
end

-- 中文一行 + 英文小字一行;只有一种语言时只出一行
local function pair(cls, zh, en)
    zh, en = type(zh) == "string" and zh or "", type(en) == "string" and en or ""
    if zh == "" and en == "" then return nil end
    local html = '<p class="' .. cls .. '">' .. esc(zh ~= "" and zh or en)
    if zh ~= "" and en ~= "" then html = html .. '<br/><span class="en">' .. esc(en) .. "</span>" end
    return html .. "</p>"
end

--- One episode of AI Podcast: /mcp-data/ep/<id>.json (bilingual transcript,
--- key points) laid out on the device. The largest episodes are ~800 KB and
--- GitHub Pages takes ~7 s per 90 KB from this Kindle, hence the long timeout.
function M.fetchArticle(id)
    assert(M.validId(id), "Invalid article ID")
    local data, err = M.request("/mcp-data/ep/" .. id .. ".json", 120)
    if type(data) ~= "table" or data.id ~= id then return nil, err or "Episode unavailable" end
    local parts = {}
    local function add(html) if html then parts[#parts + 1] = html end end
    local function section(title, list)
        if type(list) ~= "table" or #list == 0 then return end
        add("<h2>" .. title .. "</h2>")
        for _, item in ipairs(list) do
            if type(item) == "table" then add(pair("point", item.zh, item.en)) end
        end
    end
    if type(data.tEn) == "string" and data.tEn ~= "" and data.tEn ~= data.tZh then
        add('<p class="en-title">' .. esc(data.tEn) .. "</p>")
    end
    add(pair("summary", data.sZh, data.sEn))
    local brief, insights = type(data.brief) == "table" and data.brief or {}, type(data.insights) == "table" and data.insights or {}
    section("速览", brief.tldr)
    section("核心观点", insights.consensus)
    section("反共识", insights.contrarian)
    -- Sponsor reads: ads = { { sec = section index (0-based), from = , to = turn indexes (0-based, inclusive) } }
    local skip = {}
    for _, ad in ipairs(type(data.ads) == "table" and data.ads or {}) do
        if type(ad) == "table" and ad.sec and ad.from and ad.to then
            for turn = ad.from, ad.to do skip[ad.sec .. ":" .. turn] = true end
        end
    end
    local transcript = type(data.transcript) == "table" and data.transcript or {}
    for si, sec in ipairs(transcript) do
        if type(sec) == "table" then
            local zh, en = type(sec.secZh) == "string" and sec.secZh or "", type(sec.sec) == "string" and sec.sec or ""
            local heading = esc(zh ~= "" and zh or en)
            if zh ~= "" and en ~= "" then heading = heading .. ' <span class="en">' .. esc(en) .. "</span>" end
            add("<h2>" .. heading .. "</h2>")
            for ti, turn in ipairs(type(sec.turns) == "table" and sec.turns or {}) do
                if type(turn) == "table" and not skip[(si - 1) .. ":" .. (ti - 1)] then
                    local html = pair("turn", turn.zh, turn.en)
                    if html and type(turn.spk) == "string" and turn.spk ~= "" then
                        html = html:gsub('^<p class="turn">', '<p class="turn"><b>' .. esc(turn.spk) .. "</b>　", 1)
                    end
                    add(html)
                end
            end
        end
    end
    if type(data.src) == "string" and data.src ~= "" then
        add('<p class="qm-meta">原视频：<a href="' .. esc(data.src) .. '">' .. esc(data.src) .. "</a></p>")
    end
    local body = table.concat(parts, "\n")
    if #body == 0 then return nil, "Full transcript unavailable" end
    if #body > M.MAX_BODY then return nil, "Episode too large for this device" end
    return { body = body, format = "html", version = "aipodcast-1", base_url = M.ORIGIN, media_version = 1 }
end

return M
